-- Copy of the `seedsmans` D1 database's tables as they were on 2 Nov 2026 (applied by migrations
-- 0001_core.sql, 0002_sample_settings.sql and 0003_integrity.sql, which are not in this repository).
-- For reference and for local testing (npm run db:local). Do not run against the live database.
CREATE TABLE user (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, emailVerified INTEGER NOT NULL DEFAULT 0, image TEXT, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL, role TEXT NOT NULL DEFAULT 'field');
CREATE TABLE session (id TEXT PRIMARY KEY, expiresAt INTEGER NOT NULL, token TEXT NOT NULL UNIQUE, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL, ipAddress TEXT, userAgent TEXT, userId TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE);
CREATE TABLE account (id TEXT PRIMARY KEY, accountId TEXT NOT NULL, providerId TEXT NOT NULL, userId TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, accessToken TEXT, refreshToken TEXT, idToken TEXT, accessTokenExpiresAt INTEGER, refreshTokenExpiresAt INTEGER, scope TEXT, password TEXT, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL);
CREATE TABLE verification (id TEXT PRIMARY KEY, identifier TEXT NOT NULL, value TEXT NOT NULL, expiresAt INTEGER NOT NULL, createdAt INTEGER, updatedAt INTEGER);
CREATE TABLE customers (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL, phone TEXT NOT NULL, source TEXT NOT NULL, consent INTEGER NOT NULL DEFAULT 0, notes TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, deleted_at TEXT, created_by TEXT REFERENCES user(id));
CREATE TABLE properties (id TEXT PRIMARY KEY, customer_id TEXT NOT NULL REFERENCES customers(id), address TEXT NOT NULL, suburb TEXT NOT NULL, access TEXT NOT NULL DEFAULT '', hazards TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, deleted_at TEXT);
CREATE TABLE hedge_assets (id TEXT PRIMARY KEY, property_id TEXT NOT NULL REFERENCES properties(id), name TEXT NOT NULL, species TEXT, inactive INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE hedge_measurements (id TEXT PRIMARY KEY, hedge_id TEXT NOT NULL REFERENCES hedge_assets(id), geometry TEXT CHECK(geometry IS NULL OR json_valid(geometry)), inputs TEXT NOT NULL CHECK(json_valid(inputs)), source TEXT NOT NULL, measured_by TEXT REFERENCES user(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE rate_library (id TEXT PRIMARY KEY, effective_date TEXT NOT NULL, expiry_date TEXT, active INTEGER NOT NULL DEFAULT 1, approval_status TEXT NOT NULL DEFAULT 'sample', snapshot TEXT NOT NULL CHECK(json_valid(snapshot)), created_by TEXT REFERENCES user(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE quotes (id TEXT PRIMARY KEY, number TEXT NOT NULL UNIQUE, customer_id TEXT NOT NULL REFERENCES customers(id), property_id TEXT NOT NULL REFERENCES properties(id), status TEXT NOT NULL DEFAULT 'Draft', revision INTEGER NOT NULL DEFAULT 1, hedges TEXT NOT NULL CHECK(json_valid(hedges)), calculation TEXT NOT NULL CHECK(json_valid(calculation)), assumptions TEXT NOT NULL DEFAULT '', exclusions TEXT NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '', valid_until TEXT NOT NULL, portal_token_hash TEXT UNIQUE, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, created_by TEXT REFERENCES user(id));
CREATE TABLE quote_revisions (id TEXT PRIMARY KEY, quote_id TEXT NOT NULL REFERENCES quotes(id), revision INTEGER NOT NULL, snapshot TEXT NOT NULL CHECK(json_valid(snapshot)), created_by TEXT REFERENCES user(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(quote_id, revision));
CREATE TABLE quote_acceptances (id TEXT PRIMARY KEY, quote_id TEXT NOT NULL UNIQUE REFERENCES quotes(id), revision INTEGER NOT NULL, name TEXT NOT NULL, accepted_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, terms_version TEXT NOT NULL);
CREATE TABLE jobs (id TEXT PRIMARY KEY, quote_id TEXT NOT NULL UNIQUE REFERENCES quotes(id), customer_id TEXT NOT NULL REFERENCES customers(id), property_id TEXT NOT NULL REFERENCES properties(id), title TEXT NOT NULL, start TEXT NOT NULL, end TEXT NOT NULL, crew TEXT NOT NULL, status TEXT NOT NULL, notes TEXT NOT NULL DEFAULT '', actual_hours REAL NOT NULL DEFAULT 0 CHECK(actual_hours>=0), waste REAL NOT NULL DEFAULT 0 CHECK(waste>=0), next_cut TEXT NOT NULL DEFAULT '', started_at TEXT, completed_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE job_assignments (id TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES jobs(id), user_id TEXT NOT NULL REFERENCES user(id), UNIQUE(job_id,user_id));
CREATE TABLE tasks (id TEXT PRIMARY KEY, title TEXT NOT NULL, due TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Open', customer_id TEXT REFERENCES customers(id), job_id TEXT REFERENCES jobs(id), automation_key TEXT UNIQUE, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE enquiries (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL, phone TEXT NOT NULL, address TEXT NOT NULL, details TEXT NOT NULL CHECK(json_valid(details)), status TEXT NOT NULL DEFAULT 'New enquiry', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE photos (id TEXT PRIMARY KEY, job_id TEXT REFERENCES jobs(id), property_id TEXT REFERENCES properties(id), hedge_id TEXT REFERENCES hedge_assets(id), category TEXT NOT NULL CHECK(category IN ('before','after','issue','enquiry')), object_key TEXT NOT NULL UNIQUE, caption TEXT NOT NULL, file_name TEXT NOT NULL, content_type TEXT NOT NULL, bytes INTEGER NOT NULL, created_by TEXT REFERENCES user(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, enquiry_id TEXT REFERENCES enquiries(id));
CREATE TABLE recurring_service_plans (id TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES jobs(id), property_id TEXT NOT NULL REFERENCES properties(id), due TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE invoices (id TEXT PRIMARY KEY, job_id TEXT NOT NULL UNIQUE REFERENCES jobs(id), number TEXT UNIQUE, amount_cents INTEGER NOT NULL CHECK(amount_cents>=0), status TEXT NOT NULL DEFAULT 'Draft', due TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE automation_rules (id TEXT PRIMARY KEY, name TEXT NOT NULL, trigger_type TEXT NOT NULL, days_offset INTEGER NOT NULL, active INTEGER NOT NULL DEFAULT 1, template TEXT NOT NULL);
CREATE TABLE communications (id TEXT PRIMARY KEY, customer_id TEXT REFERENCES customers(id), channel TEXT NOT NULL, destination TEXT NOT NULL, template TEXT NOT NULL, status TEXT NOT NULL, idempotency_key TEXT UNIQUE, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit_log (id TEXT PRIMARY KEY, actor_id TEXT REFERENCES user(id), entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, action TEXT NOT NULL, snapshot TEXT NOT NULL CHECK(json_valid(snapshot)), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE business_settings (id TEXT PRIMARY KEY, value TEXT NOT NULL CHECK(json_valid(value)), updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE request_limits (key TEXT PRIMARY KEY, count INTEGER NOT NULL, expires INTEGER NOT NULL);
CREATE INDEX session_user ON session(userId);
CREATE INDEX properties_customer ON properties(customer_id);
CREATE INDEX jobs_start ON jobs(start);
CREATE INDEX tasks_due ON tasks(status,due);
CREATE INDEX audit_entity ON audit_log(entity_type,entity_id);
CREATE TRIGGER no_crew_overlap_insert BEFORE INSERT ON jobs WHEN NEW.status!='Cancelled' BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM jobs WHERE crew=NEW.crew AND status!='Cancelled' AND start<NEW.end AND end>NEW.start) THEN RAISE(ABORT,'Crew overlap') END;
END;
CREATE TRIGGER no_crew_overlap_update BEFORE UPDATE OF start,end,crew,status ON jobs WHEN NEW.status!='Cancelled' BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM jobs WHERE id!=NEW.id AND crew=NEW.crew AND status!='Cancelled' AND start<NEW.end AND end>NEW.start) THEN RAISE(ABORT,'Crew overlap') END;
END;
CREATE TRIGGER protect_quote_revision_update BEFORE UPDATE ON quote_revisions BEGIN SELECT RAISE(ABORT,'Quote history is append-only'); END;
CREATE TRIGGER protect_quote_revision_delete BEFORE DELETE ON quote_revisions BEGIN SELECT RAISE(ABORT,'Quote history is append-only'); END;
